stdout:
user www-data;
worker_processes auto;
worker_rlimit_nofile 65535;
error_log /var/log/nginx/error.log;
pid /run/nginx.pid;
include /etc/nginx/modules-enabled/*.conf;

events {
	worker_connections 1024;
	use epoll;
	multi_accept on;
}

http {
	# Main settings
	sendfile on;
	tcp_nopush on;
	tcp_nodelay on;
	client_max_body_size 256m;
	send_timeout 60;
	keepalive_timeout 30s;
	server_tokens off;
	charset utf-8;

	# Proxy settings
	proxy_redirect off;
	proxy_set_header Host $host;
	proxy_set_header X-Real-IP $remote_addr;
	proxy_connect_timeout 30;
	proxy_send_timeout 180;
	proxy_read_timeout 300;

	# Compression
	gzip on;
	gzip_vary on;
	gzip_comp_level 6;
	gzip_min_length 1024;

	include /etc/nginx/conf.d/*.conf;
	include /etc/nginx/conf.d/domains/*.conf;
}

options {
	directory "/var/cache/bind";
	dnssec-validation auto;
	listen-on-v6 { any; };
	allow-recursion { 127.0.0.1; ::1; };
	allow-transfer { "none"; };
	version "unknown";
	statistics-file "/var/cache/bind/named.stats";
};

// This is the primary configuration file for the BIND DNS server named.
include "/etc/bind/named.conf.options";
include "/etc/bind/named.conf.local";
include "/etc/bind/named.conf.default-zones";

zone "example.com" {type master; file "/home/admin/conf/dns/example.com.db";};
zone "acme-bakery.com" {type master; file "/home/bob/conf/dns/acme-bakery.com.db";};

SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin

# m h dom mon dow user	command
17 *	* * *	root	cd / && run-parts --report /etc/cron.hourly
25 6	* * *	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.daily; }
47 6	* * 7	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.weekly; }
52 6	1 * *	root	test -x /usr/sbin/anacron || { cd / && run-parts --report /etc/cron.monthly; }

service auth {
  unix_listener auth-client {
    group = Debian-exim
    mode = 0660
  }
}

protocol imap {
  mail_plugins = $mail_plugins quota imap_quota
}

passdb {
  driver = passwd-file
  args = scheme=MD5-CRYPT username_format=%n /etc/exim4/domains/%d/passwd
}
userdb {
  driver = passwd-file
  args = /etc/exim4/domains/%d/passwd
}
